import rehypeShikiFromHighlighter from "@shikijs/rehype/core";
import rehypeKatex from "rehype-katex";
import rehypeStringify from "rehype-stringify";
import remarkGfm from "remark-gfm";
import remarkMath from "remark-math";
import remarkParse from "remark-parse";
import remarkRehype from "remark-rehype";
import { createHighlighter, createJavaScriptRegexEngine } from "shiki";
import { unified } from "unified";
import { visit } from "unist-util-visit";

import { trailingSlashRedirectUrl } from "../../utils/canonical.ts";
import { transformerSlideHighlight } from "./highlight.ts";
import { rehypeShikiToClasses } from "./shiki-classes.ts";
import type { ColorTheme } from "./types.ts";

/**
 * 全 bundledLanguages を読むと CI の 5s timeout を超える。
 * デッキで使う言語だけ渡し、未知は javascript に落とす。
 */
const SLIDE_SHIKI_LANGS = [
	"typescript",
	"javascript",
	"tsx",
	"jsx",
	"json",
	"bash",
	"shellscript",
	"html",
	"css",
	"markdown",
	"python",
	"go",
	"rust",
	"yaml",
	"toml",
] as const;

const highlighterPromise = createHighlighter({
	themes: ["min-dark", "min-light"],
	langs: [...SLIDE_SHIKI_LANGS],
	// Cloudflare / workerd は Oniguruma の WASM を instantiate できない
	engine: createJavaScriptRegexEngine(),
});

type ImageNode = {
	type: "image";
	url: string;
};

type LinkNode = {
	type: "link";
	url: string;
};

function rewriteRelativeImages(slug: string) {
	return () => (tree: unknown) => {
		visit(tree as never, "image", (node: ImageNode) => {
			if (!node.url || /^(https?:|data:|\/)/i.test(node.url)) {
				return;
			}
			const cleaned = node.url.replace(/^\.\//, "");
			node.url = cleaned.startsWith(`${slug}/`)
				? `/slides/media/${cleaned}`
				: `/slides/media/${slug}/${cleaned}`;
		});
	};
}

function rewriteInternalPageLinks() {
	return (tree: unknown) => {
		visit(tree as never, "link", (node: LinkNode) => {
			if (!node.url || !node.url.startsWith("/") || node.url.startsWith("//")) {
				return;
			}
			const location = trailingSlashRedirectUrl(
				new URL(node.url, "https://ta93abe.com"),
			);
			if (!location) {
				return;
			}
			node.url = `${location.pathname}${location.search}${location.hash}`;
		});
	};
}

export async function markdownToHtml(
	markdown: string,
	slug: string,
	theme: ColorTheme = "dark",
): Promise<string> {
	const highlighter = await highlighterPromise;
	const themeName = theme === "light" ? "min-light" : "min-dark";
	const file = await unified()
		.use(remarkParse)
		.use(remarkGfm)
		.use(remarkMath)
		.use(rewriteRelativeImages(slug))
		.use(rewriteInternalPageLinks)
		.use(remarkRehype, { allowDangerousHtml: false })
		.use(rehypeKatex, { strict: "ignore" })
		.use(() =>
			rehypeShikiFromHighlighter(highlighter, {
				theme: themeName,
				fallbackLanguage: "javascript",
				transformers: [transformerSlideHighlight()],
			}),
		)
		.use(rehypeShikiToClasses)
		.use(rehypeStringify)
		.process(markdown);

	return String(file).trim();
}
export function splitSlides(body: string): string[] {
	const lines = body.replace(/\r\n/g, "\n").split("\n");
	const chunks: string[] = [];
	let buffer: string[] = [];
	let fenceChar: "`" | "~" | null = null;
	let fenceLen = 0;

	const flush = () => {
		const text = buffer.join("\n").trim();
		if (text.length > 0) {
			chunks.push(text);
		}
		buffer = [];
	};

	for (const line of lines) {
		if (!fenceChar) {
			const open = line.match(/^(`{3,}|~{3,})/);
			if (open) {
				fenceChar = open[1][0] as "`" | "~";
				fenceLen = open[1].length;
				buffer.push(line);
				continue;
			}
			if (/^-{3,}\s*$/.test(line)) {
				flush();
				continue;
			}
			buffer.push(line);
			continue;
		}

		buffer.push(line);
		const close = line.match(/^(`{3,}|~{3,})\s*$/);
		if (close && close[1][0] === fenceChar && close[1].length >= fenceLen) {
			fenceChar = null;
			fenceLen = 0;
		}
	}

	flush();
	return chunks;
}
function stripFences(markdown: string): string {
