import type { Element } from "hast";
import { SKIP, visit } from "unist-util-visit";

function classTokens(node: Element): string[] {
	const raw = [node.properties?.className, node.properties?.class].flatMap(
		(value) => {
			if (Array.isArray(value)) {
				return value.map(String);
			}
			if (typeof value === "string") {
				return [value];
			}
			return [];
		},
	);
	return raw.flatMap((item) => item.split(/\s+/)).filter(Boolean);
}

function readStyle(value: unknown): string | null {
	if (typeof value === "string") {
		return value;
	}
	if (Array.isArray(value)) {
		return value.map(String).join(";");
	}
	return null;
}

function normalizeColor(value: string): string | null {
	const trimmed = value.trim().toLowerCase();
	const hex = trimmed.match(/^#([0-9a-f]{3,8})$/);
	if (hex) {
		return hex[1];
	}
	return null;
}

export function colorClassName(color: string): string | null {
	const hex = normalizeColor(color);
	return hex ? `shiki-fg-${hex}` : null;
}

function isKatexTree(node: Element): boolean {
	return classTokens(node).some(
		(token) => token === "katex" || token.startsWith("katex-"),
	);
}

/**
 * Shiki のインライン style をクラスへ移す。me の CSP は style-src-elem が
 * 'self' なので、ハイライト色はテーマ CSS 側で持つ。
 * KaTeX の strut など、コード以外の style 属性は消さない。
 */
export function rehypeShikiToClasses() {
	return (tree: unknown) => {
		visit(tree as never, "element", (node: Element) => {
			if (isKatexTree(node)) {
				return SKIP;
			}
			rewriteShikiStyle(node);
		});
	};
}

function rewriteShikiStyle(node: Element) {
	const style = readStyle(node.properties?.style);
	if (!style || style.trim() === "") {
		return;
	}

	const classes = classTokens(node);
	const color = style.match(/(?:^|;)\s*color:\s*([^;]+)/i);
	if (color) {
		const className = colorClassName(color[1]);
		if (className) {
			classes.push(className);
		}
	}
	if (/font-style:\s*italic/i.test(style)) {
		classes.push("shiki-italic");
	}
	if (/font-weight:\s*(bold|[5-9]00)/i.test(style)) {
		classes.push("shiki-bold");
	}
	if (/text-decoration:\s*underline/i.test(style)) {
		classes.push("shiki-underline");
	}

	node.properties.className = classes;
	delete node.properties.style;
	delete node.properties.class;
}
import type { Element } from "hast";
import type { ShikiTransformer } from "shiki";

import { parseCodeFenceMeta } from "./code-meta.ts";

function rawMetaString(meta: Record<string, unknown> | undefined): string {
	const value = meta?.["__raw"];
	return typeof value === "string" ? value : "";
}

function rawMeta(ctx: { options: { meta?: Record<string, unknown> } }): string {
	return rawMetaString(ctx.options.meta);
}

export function transformerSlideHighlight(): ShikiTransformer {
	return {
		name: "slide-highlight",
		pre(node) {
			const parsed = parseCodeFenceMeta(rawMeta(this));
			if (parsed.always.length > 0 || parsed.steps.length > 0) {
				this.addClassToHast(node, "has-highlight");
			}
			if (parsed.steps.length > 0) {
				this.addClassToHast(node, "has-click-highlight");
			}
		},
		line(node: Element, line) {
			const parsed = parseCodeFenceMeta(rawMeta(this));
			if (parsed.always.includes(line)) {
				this.addClassToHast(node, "line-highlighted");
			}
			for (const [step, lines] of parsed.steps.entries()) {
				if (lines.includes(line)) {
					node.properties = node.properties ?? {};
					node.properties["data-click-highlight"] = String(step);
				}
			}
		},
	};
}
	let extra = 0;
	for (const child of list.childNodes) {
		if (!(child instanceof HTMLElement) || child.rawTagName !== "li") {
			continue;
		}
		extra += 1;
		child.classList.add("fragment");
		child.setAttribute("data-click", String(start + extra));
	}

	if (extra === 0) {
		throw new DeckError("<!-- clicks --> のリストに項目がありません");
	}

	return { html: root.toString(), extra };
}

export async function materializeSlideHtml(
	source: string,
	toHtml: (markdown: string) => Promise<string>,
): Promise<{ html: string; clicks: number }> {
	const parts = splitClickFragments(source);
	let html = "";
	let clicks = 0;

	for (const [index, rawPart] of parts.entries()) {
		const wantsListClicks = /<!--\s*clicks\s*-->/.test(rawPart);
		const markdown = rawPart.replace(CLICKS_MARK, "\n").trim();
		if (!markdown) {
			throw new DeckError("click のあいだが空です");
		}

		let partHtml = await toHtml(markdown);

		if (index > 0) {
			clicks += 1;
			partHtml = `<div class="fragment" data-click="${clicks}">${partHtml}</div>`;
		}

		if (wantsListClicks) {
			const applied = applyListClicks(partHtml, clicks);
			partHtml = applied.html;
			clicks += applied.extra;
		}

		html += (html ? "\n" : "") + partHtml;
	}

	clicks = Math.max(clicks, countHighlightClicks(html));
	if (!html) {
		throw new DeckError("本文が空です");
	}

	return { html, clicks };
}
export type HighlightMeta = {
	always: number[];
	steps: number[][];
};

function parseLineRange(spec: string): number[] {
	const lines: number[] = [];
	for (const part of spec.split(",")) {
		const trimmed = part.trim();
		if (trimmed === "") {
			continue;
		}
		const range = trimmed.match(/^(\d+)-(\d+)$/);
		if (range) {
			const start = Number(range[1]);
			const end = Number(range[2]);
			const from = Math.min(start, end);
			const to = Math.max(start, end);
			for (let line = from; line <= to; line += 1) {
				lines.push(line);
			}
			continue;
		}
		if (/^\d+$/.test(trimmed)) {
			lines.push(Number(trimmed));
		}
	}
	return lines;
}

export function parseCodeFenceMeta(meta: string): HighlightMeta {
	const match = meta.match(/\{([^}]+)\}/);
	if (!match) {
		return { always: [], steps: [] };
	}
	const inner = match[1].trim();
	if (inner.includes("|")) {
		return {
			always: [],
			steps: inner.split("|").map(parseLineRange),
		};
	}
	return { always: parseLineRange(inner), steps: [] };
}

export function countHighlightClicks(html: string): number {
	let max = 0;
	for (const match of html.matchAll(/data-click-highlight="(\d+)"/g)) {
		max = Math.max(max, Number(match[1]));
	}
	return max;
}

