export function remarkSlides() {
	return (tree: Root, file: VFile) => {
		if (!isSlideDeckFile(file.path)) {
			return;
		}
		const data = file.data as AstroData;
		const frontmatter = data.astro?.frontmatter ?? {};
		const slug = String(frontmatter.slug ?? "");

		const chunks = splitAtBreaks(tree.children);
		if (chunks.length === 0) {
			file.fail("スライドが 1 枚もありません");
		}
		const slides = chunks.map((chunk, index) => parseSlide(new SlideContext(file, index), chunk));
		const firstCover = slides.findIndex((slide) => slide.type === "cover");
		const total = slides.length;

		tree.children = slides.map((slide, index) => {
			rewriteMedia(slide.body, slug);
			const keepLevel = firstCover === index || (firstCover === -1 && index === 0);
			shiftHeadings(slide.body, keepLevel ? 0 : 1);

			const body: Content[] =
				slide.type === "cover" && firstCover === index
					? [
							box("header", {}, [], []),
							box("div", { className: ["slide-cover-main"] }, slide.body),
						]
					: slide.body;
			if (slide.type === "cover" && firstCover === index) {
				// header は hast を直接渡す（frontmatter から組む表紙メタ）
				body[0] = box("header", {}, [], [coverMeta(frontmatter)]);
				(body[0] as Box).data.hName = "div";
				(body[0] as Box).data.hProperties = { dataSlideCoverMeta: "" };
			}

			const sectionChildren: Content[] = [box("div", { className: ["slide-body"] }, body)];
			if (slide.notes) {
				sectionChildren.push(box("div", { className: ["speaker-notes"] }, [], [text(slide.notes)]));
			}
			const first = index === 0;
			return box(
				"section",
				{
					className: first ? ["slide", "is-active"] : ["slide"],
					dataType: slide.type,
					dataIndex: String(index + 1),
					dataClicks: String(slide.clicks),
					id: `s${index + 1}`,
					ariaLabel: `${index + 1} / ${total}`,
					...(first ? {} : { hidden: true, inert: true }),
				},
				sectionChildren,
			) as RootContent;
		});

		const info: SlideDeckRenderInfo = {
			slideCount: total,
			slides: slides.map((slide) => ({ type: slide.type, clicks: slide.clicks })),
		};
		data.astro = data.astro ?? {};
		data.astro.frontmatter = { ...frontmatter, ...info };
	};
}

