import { oauthAuthorizationServerMetadata } from "./oauth-discovery.ts";

function agentAuthMetadata(siteUrl: string) {
	return {
		skill: `${siteUrl}/auth.md`,
		register_uri: `${siteUrl}/agent/auth`,
		identity_types_supported: ["anonymous"],
		anonymous: {
			credential_types_supported: ["none"],
			claim_uri: `${siteUrl}/agent/claim`,
		},
	};
}

export function oauthAuthorizationServer(siteUrl: string) {
	return oauthAuthorizationServerMetadata({
		issuer: siteUrl,
		documentationUrl: `${siteUrl}/auth.md`,
		agentAuth: agentAuthMetadata(siteUrl),
	});
}

export function oauthProtectedResource(siteUrl: string) {
	return {
		resource: siteUrl,
		// RFC 9728 §2: issuer identifiers, not the metadata document URL.
		// Clients insert `/.well-known/oauth-authorization-server` once (RFC 8414 §3).
		authorization_servers: [siteUrl],
		scopes_supported: ["public:read"],
		bearer_methods_supported: ["header"],
		resource_signing_alg_values_supported: [],
		// agent_auth is not an RFC 9728 PRM field. auth.md Step 1 reads it
		// from Authorization Server metadata only.
	};
}
	grant_types_supported: string[];
	token_endpoint_auth_methods_supported: string[];
	service_documentation: string;
	note: string;
	agent_auth: AgentAuth;
};

export function oauthAuthorizationServerMetadata<AgentAuth>(input: {
	issuer: string;
	documentationUrl: string;
	agentAuth: AgentAuth;
}): OauthAuthorizationServerMetadata<AgentAuth> {
	return {
		issuer: input.issuer,
		// Empty arrays override RFC defaults. "none" is a real OAuth/OIDC value
		// (empty authorization response / unauthenticated token client), not
		// "unsupported". An omitted grant list defaults to authorization_code
		// + implicit; an omitted token auth list defaults to client_secret_basic.
		// Do not advertise urn:workos:agent-auth:grant-type:claim — that grant
		// is used at a token endpoint this site does not operate.
		response_types_supported: [],
		grant_types_supported: [],
		token_endpoint_auth_methods_supported: [],
		service_documentation: input.documentationUrl,
		note: "agent_auth discovery only. This host is not an OpenID Connect Provider and does not mint OAuth access tokens.",
		agent_auth: input.agentAuth,
	};
}
