# Cloudflare インフラ（infra/alchemy.run.ts）の Plan / デプロイ
#
# - PR で infra/** か依存（package.json / lockfile / pnpm-workspace.yaml）に変更がある場合:
#   alchemy の CLI が起動するかを確かめ、alchemy plan（dry-run）を実行しログで差分を確認できる
#   （Secrets を持たない Dependabot の PR では CLI の起動確認だけ）
# - main への push で infra/** に変更がある場合: alchemy deploy を実行
# - 依存だけを変えたときの反映は workflow_dispatch（main）で行う
#
# 必要な Secrets:
# - CLOUDFLARE_API_TOKEN: Workers Scripts Write / Workers R2 Storage Write /
#   Secrets Store Write（Alchemy のステートストア読み書きに必須）/
#   Zone > Workers Routes・DNS Write（カスタムドメイン接続用）を持つトークン
# - CLOUDFLARE_ACCOUNT_ID: b0047256d1afc1be1df08289ee3be552
name: Deploy Infra

on:
  push:
    branches: [main]
    paths:
      - "infra/**"
  pull_request:
    paths:
      - "infra/**"
      - "package.json"
      - "pnpm-lock.yaml"
      - "pnpm-workspace.yaml"
  workflow_dispatch:

concurrency:
  group: deploy-infra-${{ github.event_name == 'pull_request' && github.event.number || 'main' }}
  cancel-in-progress: false

jobs:
  plan:
    if: github.event_name == 'pull_request'
    runs-on: ubuntu-latest
    env:
      HAS_CLOUDFLARE_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN != '' }}
    permissions:
      contents: read
/**
 * CMS インフラ（Alchemy v2）
 *
 * - me-images: 公開メディア（images.ta93abe.com）
 * - me-content: 非公開本文（Worker binding のみ。カスタムドメインなし）
 * - content-events: R2 md/ の create/delete で index を再構築する Queue
 * - me-slides-pdf: スライド PDF を Browser Run で焼く Queue（max_concurrency は wrangler）
 *
 * HMAC シークレットは wrangler secret:
 *   wrangler secret put CONTENT_HMAC_SECRET
 *
 * デプロイ:
 *   pnpm infra:deploy
 */
import * as Alchemy from "alchemy";
import * as Cloudflare from "alchemy/Cloudflare";
import * as Effect from "effect/Effect";

const SITE_ORIGIN = "https://ta93abe.com";
const IMAGES_DOMAIN = "images.ta93abe.com";

export default Alchemy.Stack(
	"me-cms",
	{ providers: Cloudflare.providers(), state: Cloudflare.state() },
	Effect.gen(function* () {
		const content = yield* Cloudflare.R2.Bucket("Content", {
			name: "me-content",
		});

		const contentEvents = yield* Cloudflare.Queues.Queue("ContentEvents", {
			name: "content-events",
		});

		const slidesPdf = yield* Cloudflare.Queues.Queue("SlidesPdf", {
			name: "me-slides-pdf",
		});

		yield* Cloudflare.R2.BucketEventNotification("ContentMarkdownEvents", {
			bucketName: content.bucketName,
			queueId: contentEvents.queueId,
			rules: [
				{
					actions: [
						"PutObject",
						"CopyObject",
						"CompleteMultipartUpload",
						"DeleteObject",
					],
					prefix: "md/",
					suffix: ".md",
					description: "rebuild indexes when published markdown changes",
				},
			],
		});

		// 公開メディア。CORS はブラウザからの直アップロード（記事の添付）のプリフライト用。
		const images = yield* Cloudflare.R2.Bucket("Images", {
			name: "me-images",
			domains: [{ name: IMAGES_DOMAIN }],
			cors: [
				{
					allowedMethods: ["GET", "PUT", "HEAD"],
					allowedOrigins: [SITE_ORIGIN, "http://localhost:4321"],
					allowedHeaders: ["*"],
					exposeHeaders: ["ETag"],
					maxAgeSeconds: 3000,
				},
			],
		});

		return {
			imagesBucket: images.bucketName,
			imagesPublicUrl: `https://${IMAGES_DOMAIN}`,
			contentBucket: content.bucketName,
			contentEventsQueue: contentEvents.queueName,
			slidesPdfQueue: slidesPdf.queueName,
		};
	}),
);

