import type { LinkCardData } from "./link-card.ts";
import type { TweetEmbedData } from "./tweet.ts";
import type { YoutubeEmbedData } from "./youtube.ts";

export const EMBED_TTL_MS = 7 * 24 * 60 * 60 * 1000;

export type BlogEmbedTweet = {
	kind: "tweet";
	id: string;
	href: string;
};

export type BlogEmbedYoutube = {
	kind: "youtube";
	id: string;
	href: string;
};

export type BlogEmbedLink = {
	kind: "link";
	href: string;
};

export type BlogEmbedSpotify = {
	kind: "spotify";
	href: string;
};

export type BlogEmbed =
	| BlogEmbedTweet
	| BlogEmbedYoutube
	| BlogEmbedLink
	| BlogEmbedSpotify;

export type EmbedCacheRecord = {
	url: string;
	kind: "link" | "tweet" | "youtube" | "spotify";
	fetchedAt: string;
	expiresAt: string;
	link?: LinkCardData;
	tweet?: TweetEmbedData | null;
	youtube?: YoutubeEmbedData | null;
};

export type EmbedLookups = {
	tweets: Map<string, TweetEmbedData | null>;
	videos: Map<string, YoutubeEmbedData | null>;
	links: Map<string, LinkCardData>;
};

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

function nonEmptyString(value: unknown): string | undefined {
	return typeof value === "string" && value.length > 0 ? value : undefined;
}

async function sha256Hex(value: string): Promise<string> {
	const digest = await crypto.subtle.digest(
		"SHA-256",
		new TextEncoder().encode(value),
	);
	return Array.from(new Uint8Array(digest), (byte) =>
		byte.toString(16).padStart(2, "0"),
	).join("");
}

export async function getContentBucket(): Promise<R2Bucket | undefined> {
	try {
		const { env } = await import("cloudflare:workers");
		const content = (env as { CONTENT?: R2Bucket }).CONTENT;
		return content;
	} catch {
		return undefined;
	}
}
