 */
const blog = defineCollection({
	loader: glob({ pattern: "*.mdx", base: "./src/content/blog" }),
	schema: z
		.object({
			title: z.string().trim().min(1),
			excerpt: z.string().trim().min(1),
			tags: z.array(z.string().trim().min(1)).default([]),
			date: z.coerce.date(),
			updatedDate: z.coerce.date().optional(),
