import { FEATURED_WORKS } from "@/config/site";

interface Props {
	source: "works" | "about";
}

const { source } = Astro.props;

const isExternalHref = (href: string) =>
	href.startsWith("https://") || href.startsWith("http://");
---

<ul class="featured-works-list">
	{
		FEATURED_WORKS.map((work) => {
			const external = isExternalHref(work.href);
			return (
				<li>
					<a
						href={work.href}
						class="featured-works-link"
						aria-label={work.title}
						data-featured-work={source === "works" ? true : undefined}
						target={external ? "_blank" : undefined}
						rel={external ? "noopener noreferrer" : undefined}
					>
						<span class="featured-works-title">{work.title}</span>
						<span class="featured-works-excerpt">{work.excerpt}</span>
					</a>
				</li>
			);
		})
	}
</ul>

<style>
	.featured-works-list {
		margin: 0;
		padding: 0;
		list-style: none;
		border-top: 1px solid var(--border-color);
		border-bottom: 1px solid var(--border-color);
	}

	.featured-works-link {
		display: flex;
		flex-direction: column;
		gap: 0.25rem;
		padding: 1rem 0;
		text-decoration: none;
		color: inherit;
		border-top: 1px solid var(--border-color);
		transition: color 0.15s ease;
	}

	.featured-works-list li:first-child .featured-works-link {
		border-top: 0;
	}

	.featured-works-title {
		font-size: 1rem;
		font-weight: 700;
		line-height: 1.4;
		color: var(--text-primary);
	}

	.featured-works-excerpt {
		font-size: 0.875rem;
		line-height: 1.7;
		color: var(--text-secondary);
	}

	.featured-works-link:hover .featured-works-title,
	.featured-works-link:focus-visible .featured-works-title {
		color: var(--primary-color);
	}

	@media (prefers-reduced-motion: reduce) {
		.featured-works-link {
			transition: none;
		}
	}
</style>

<script>
	document.querySelectorAll("[data-featured-work]").forEach((link) => {
		link.addEventListener("click", () => {
			window.posthog?.capture("home_featured_clicked", {
				title: link
					.querySelector(".featured-works-title")
					?.textContent?.trim(),
				href: link.getAttribute("href"),
				surface: "works",
			});
		});
	});
</script>
---
import * as simpleIcons from "simple-icons";
import type { SimpleIcon } from "simple-icons";
import { CUSTOM_ICONS } from "@/data/custom-icons";
import linksData from "@/data/links.json";

interface ResolvedIcon {
	path: string;
	hex: string;
	viewBox: string;
	stroke?: {
		color: string;
		width: string;
	};
}

const resolveIcon = (slug: string): ResolvedIcon => {
	const custom = CUSTOM_ICONS[slug];
	if (custom) {
		return {
			path: custom.path,
			hex: custom.hex,
			viewBox: custom.viewBox ?? "0 0 24 24",
			stroke: custom.stroke,
		};
	}

	const key = `si${slug.charAt(0).toUpperCase()}${slug.slice(1)}`;
	const icon = (simpleIcons as unknown as Record<string, SimpleIcon>)[key];
	if (!icon) {
		throw new Error(
			`Unknown icon slug "${slug}". simple-icons のスラッグを指定するか、src/data/custom-icons.ts に追加してください。`,
		);
	}
	return { path: icon.path, hex: `#${icon.hex}`, viewBox: "0 0 24 24" };
};

const links = linksData.links.map((link) => ({
	...link,
	iconData: resolveIcon(link.icon),
}));
---

<ul class="sns-links sns-list">
	{
		links.map((link) => (
			<li>
				<a
					href={link.url}
					target="_blank"
					rel="me noopener noreferrer"
					class="sns-row"
					aria-label={link.name}
				>
					<svg
						viewBox={link.iconData.viewBox}
						class="sns-row-icon"
						aria-hidden="true"
					>
						{link.iconData.stroke ? (
							<path
								d={link.iconData.path}
								fill="none"
								stroke={link.iconData.stroke.color}
								stroke-width={link.iconData.stroke.width}
								stroke-linecap="round"
								stroke-linejoin="round"
							/>
						) : (
							<path d={link.iconData.path} fill={link.iconData.hex} />
						)}
					</svg>
					<span class="sns-row-name">{link.name}</span>
					<span class="sns-row-host">{new URL(link.url).host}</span>
				</a>
			</li>
		))
	}
</ul>

<style>
	.sns-list {
		display: flex;
		flex-direction: column;
		margin: 0;
		padding: 0;
		list-style: none;
		border-top: 1px solid var(--border-color);
	}

	.sns-row {
		display: grid;
		grid-template-columns: 1.25rem minmax(0, 8rem) minmax(0, 1fr);
		align-items: center;
		gap: 0.75rem 1rem;
		padding: 0.9rem 0;
		text-decoration: none;
		color: inherit;
		border-bottom: 1px solid var(--border-color);
		transition: color 0.15s ease;
	}

	.sns-row:hover {
		color: var(--primary-color);
	}

	.sns-row-icon {
		width: 1.25rem;
		height: 1.25rem;
		flex-shrink: 0;
	}

	.sns-row-name {
		font-size: 0.9375rem;
		font-weight: 600;
		color: var(--text-primary);
	}

	.sns-row:hover .sns-row-name {
		color: inherit;
	}

	.sns-row-host {
		font-size: 0.8125rem;
		color: var(--text-muted);
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
	}
</style>

<script>
	document.querySelectorAll(".sns-links a[href]").forEach((link) => {
		link.addEventListener("click", () => {
			window.posthog?.capture("sns_link_clicked", {
				platform: link.getAttribute("aria-label"),
				url: link.getAttribute("href"),
			});
		});
	});
</script>
