import { deckFrontmatterSchema } from "./slides/mdx/deck-schema.ts";

/**
 * ブログ記事（ADR-0003）。公開本文の正は `src/content/blog/<slug>.mdx`。
 * ファイル名が slug で、URL は `/blog/<slug>/`。未知の frontmatter キーはビルド失敗にする。
