import { z } from "astro/zod";

/**
 * Works / Links など「1 項目 1 ファイル」のコレクション（TA-2152）。
 * スキーマと並び替えは純関数にして、Astro・Worker・テストのどこからでも使えるようにする。
 */

const nonEmpty = z.string().trim().min(1);
const order = z.number().int().nonnegative();

/** 外部の絶対 URL か、サイト内のパス（`/blog/<slug>/` など）。 */
const workHref = z.union([z.url(), z.string().regex(/^\/[^/]/)]);

/** `src/content/works/<slug>.mdx` */
export const workFrontmatterSchema = z
	.object({
		title: nonEmpty,
		/** GitHub のリポジトリか、サイト内のブログ記事 */
		href: workHref,
		excerpt: nonEmpty,
		order,
	})
	.strict();

/** `src/content/links/<slug>.mdx` */
export const linkFrontmatterSchema = z
	.object({
		name: nonEmpty,
		url: z.url(),
		/** simple-icons のスラッグか `src/data/custom-icons.ts` のキー */
		icon: nonEmpty,
		order,
	})
	.strict();

export type FeaturedWork = {
	href: string;
	title: string;
	excerpt: string;
};

export type SiteLink = {
	name: string;
	url: string;
	icon: string;
};

type Ordered = { id: string; data: { order: number } };

/**
 * `order` の昇順に並べる。同じ `order` が 2 つあると並びが決まらないので投げる（ビルド失敗）。
 */
export function sortByOrder<T extends Ordered>(
	collection: string,
	entries: readonly T[],
): T[] {
	const seen = new Map<number, string>();
	for (const entry of entries) {
		const other = seen.get(entry.data.order);
		if (other !== undefined) {
			throw new Error(
				`${collection}: order ${entry.data.order} が ${other} と ${entry.id} で重複しています`,
			);
		}
		seen.set(entry.data.order, entry.id);
	}
	return entries.toSorted((left, right) => left.data.order - right.data.order);
}

/** JSON-LD Person.sameAs。Links の URL を並び順のまま使う。 */
export function profileUrls(links: readonly SiteLink[]): string[] {
	return links.map((link) => link.url);
}

import type {
	FeaturedWork,
	SiteLink,
} from "../../src/lib/content/site-data.ts";

/**
 * ビルド時に `src/pages/site.json.ts` が出すサイトのデータ（正は `src/content/` の MDX、TA-2152）。
 * Worker は `astro:content` を読めないので、この静的アセットを読む。`blog-manifest.ts` と同じ形。
 */
export const SITE_MANIFEST_PATH = "/site.json";

export type SiteManifest = {
	works: FeaturedWork[];
	links: SiteLink[];
};

export const EMPTY_SITE_MANIFEST: SiteManifest = { works: [], links: [] };

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

function strings<K extends string>(
	value: unknown,
	keys: readonly K[],
): Record<K, string> | undefined {
	if (!isRecord(value)) {
		return undefined;
	}
	const out = {} as Record<K, string>;
	for (const key of keys) {
		const field = value[key];
		if (typeof field !== "string") {
			return undefined;
		}
		out[key] = field;
	}
	return out;
}

export function siteManifestFromJson(value: unknown): SiteManifest {
	if (!isRecord(value)) {
		return EMPTY_SITE_MANIFEST;
	}
	const works = Array.isArray(value.works)
		? value.works.flatMap((item) => {
				const work = strings(item, ["href", "title", "excerpt"] as const);
				return work ? [work] : [];
			})
		: [];
	const links = Array.isArray(value.links)
		? value.links.flatMap((item) => {
				const link = strings(item, ["name", "url", "icon"] as const);
				return link ? [link] : [];
			})
		: [];
	return { works, links };
}

type AssetFetcher = { fetch: (request: Request) => Promise<Response> };

export async function loadSiteManifest(
	assets: AssetFetcher | undefined,
	origin: string,
): Promise<SiteManifest> {
	if (!assets) {
		return EMPTY_SITE_MANIFEST;
	}
	try {
		const response = await assets.fetch(
			new Request(new URL(SITE_MANIFEST_PATH, origin)),
		);
		if (!response.ok) {
			return EMPTY_SITE_MANIFEST;
		}
		return siteManifestFromJson(await response.json());
	} catch {
		return EMPTY_SITE_MANIFEST;
	}
}

import { readdirSync } from "node:fs";
