import path from "node:path";

import { describe, expect, it } from "vitest";

import { GADGETS } from "@/data/gadgets";
import {
	applyStaticSitemapLastmod,
	createStaticSitemapSerializer,
	includeInStaticSitemap,
	toW3cLastmod,
