export const generateTalksCollectionSchema = (
	siteUrl: string,
	sameAs: readonly string[],
	description: string,
): TalksCollectionSchema => {
	const origin = originBase(siteUrl);
	return {
		"@context": "https://schema.org",
		"@type": "CollectionPage",
		name: "Talks",
		description,
		url: `${origin}/talks/`,
		inLanguage: SITE.lang,
		isPartOf: websitePart(origin),
		hasPart: TALKS.map((talk) => {
			const youtubeUrl = talkYoutubeUrl(talk);
			return {
				"@type": "Event" as const,
				name: talk.title,
				description: talk.excerpt,
				startDate: talk.date,
				url: youtubeUrl,
				eventAttendanceMode:
					"https://schema.org/OnlineEventAttendanceMode" as const,
				eventStatus: "https://schema.org/EventScheduled" as const,
				location: {
					"@type": "VirtualLocation" as const,
					url: youtubeUrl,
				},
				performer: personFields(siteUrl, sameAs),
				superEvent: {
					"@type": "Event" as const,
					name: talk.event,
				},
				recordedIn: {
					"@type": "VideoObject" as const,
					name: talk.title,
					url: youtubeUrl,
					contentUrl: youtubeUrl,
					thumbnailUrl: talkThumbnailUrl(talk),
					uploadDate: talk.date,
				},
			};
		}),
	};
};

